//! Mantle-only extension of the cluster API.
//!
//! Upstream `ProofRequestList` cannot filter by requester and only returns rows
//! oldest-first. The network gateway serves the SDK's
//! `get_filtered_proof_requests`, so a requester's history view got the oldest
//! rows of the whole cluster, filtered down to whichever few belonged to that
//! requester. `QueryProofRequests` adds the requester filter and a newest-first
//! order.
//!
//! The service is generated by `build.rs` with `tonic_build::manual`, because
//! the upstream proto lives in the published `sp1-prover-types` crate. An API
//! server without the extension answers `Unimplemented`; callers fall back to
//! `ProofRequestList` in that case.

/// Filters for `MantleClusterService/QueryProofRequests`.
///
/// Field numbers 1, 2, 3, 5 and 6 match upstream `ProofRequestListRequest`
/// (4, `handled`, is not offered) so the two requests read alike on the wire.
/// Mantle fields start at 100.
#[derive(Clone, PartialEq, prost::Message)]
pub struct ProofRequestQueryRequest {
    /// `ProofRequestStatus` values. Empty means no status filter.
    #[prost(int32, repeated, tag = "1")]
    pub proof_status: Vec<i32>,
    /// `ExecutionStatus` values. Empty means no execution-status filter.
    #[prost(int32, repeated, tag = "2")]
    pub execution_status: Vec<i32>,
    #[prost(uint64, optional, tag = "3")]
    pub minimum_deadline: Option<u64>,
    #[prost(uint32, optional, tag = "5")]
    pub limit: Option<u32>,
    #[prost(uint32, optional, tag = "6")]
    pub offset: Option<u32>,
    /// Only rows whose `requester` equals these bytes.
    #[prost(bytes = "vec", optional, tag = "100")]
    pub requester: Option<Vec<u8>>,
    /// Order by `(created_at, id)` descending instead of ascending.
    #[prost(bool, tag = "101")]
    pub newest_first: bool,
}

include!(concat!(
    env!("OUT_DIR"),
    "/mantle.cluster.MantleClusterService.rs"
));
